function dateLabel(d) { return `${d.week}, ${String(d.date).padStart(2, '0')} de dezembro`; }
function notesButton(label = 'Notas da viagem', cls = '') { return `<button class="note-button ${cls}" data-notes="trip">${icon('note')}<span>${label}</span></button>`; }
function header(wordmark = 'de férias', suffix = 'Bélgica & Países Baixos') { return `<header class="topbar"><a class="brand" href="index.html?variant=${variant}&day=${days[selected].date}">${icon('sun')} ${wordmark}<span class="brand-dot">.</span></a><span class="trip-label">${suffix} <span class="year">/ dez 2026</span></span>${notesButton()}</header>`; }
function dayStrip(cls = '') { return `<nav class="day-strip ${cls}" aria-label="Dias da viagem">${days.map((d,i)=>`<button data-day="${i}" aria-pressed="${i === selected}" ${i===selected?'aria-current="date"':''}><span>${d.week}</span><strong>${String(d.date).padStart(2,'0')}</strong><small>${d.city}</small></button>`).join('')}</nav>`; }
function activities(cls = '') { return `<div class="activities ${cls}">${days[selected].acts.map((a,i)=>`<button class="activity" data-activity="${i}"><span class="activity-time">${a[0]}</span><span class="activity-icon">${icon(a[2])}</span><span class="activity-name">${a[1]}</span>${icon('arrow','activity-arrow')}</button>`).join('')}</div>`; }
function dayControls() { return `<div class="day-controls"><button data-step="-1" aria-label="Dia anterior" ${selected===0?'disabled':''}>${icon('left')}</button><span>${String(selected+1).padStart(2,'0')} / 14 dias</span><button data-step="1" aria-label="Próximo dia" ${selected===13?'disabled':''}>${icon('arrow')}</button></div>`; }
function placeNote(cls = '') { return `<button class="place-note ${cls}" data-notes="place">${icon('note')}<span><small>PARA LEMBRAR</small><strong>${days[selected].note}</strong></span>${icon('arrow')}</button>`; }
function stay() { return `<div class="stay">${icon('bed')}<span>${days[selected].stay}</span></div>`; }
function render() {
  document.body.className = `v${variant}`;
  document.title = `${variant}. ${names[variant-1]} · de férias`;
  const d = days[selected];
  const views = [guide, atlas, boarding, postcards, now, week];
  document.getElementById('app').innerHTML = views[variant-1](d);
  document.getElementById('switcher').innerHTML = `<button data-variant="${variant===1?6:variant-1}" aria-label="Protótipo anterior">${icon('left')}</button><div class="switcher-label"><small>PROTÓTIPO ${variant} / 6</small><strong>${names[variant-1]}</strong></div><nav aria-label="Escolher protótipo">${names.map((name,i)=>`<button data-variant="${i+1}" aria-label="${i+1}. ${name}" ${variant===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}</nav><button data-variant="${variant===6?1:variant+1}" aria-label="Próximo protótipo">${icon('arrow')}</button>`;
  document.getElementById('status').textContent = `Protótipo ${variant}, ${names[variant-1]}. ${dateLabel(d)}. ${d.city}. ${d.acts.length} atividades. Horários ilustrativos.`;
  // ponytail: center only the horizontal scroller; scrollIntoView would also move the page.
  for (const selector of ['.day-strip', '.calendar-grid']) {
    const scroller = document.querySelector(selector);
    const current = scroller?.querySelector('[aria-pressed="true"]');
    if (current) scroller.scrollLeft = current.offsetLeft - scroller.offsetLeft - (scroller.clientWidth - current.clientWidth) / 2;
  }
}
function guide(d) {
 return `${header()}<main class="guide-shell"><div class="eyebrow-row"><span class="eyebrow">NOSSO PEQUENO GUIA DE VIAGEM</span><span class="eyebrow">02 a 15 dez · 14 dias juntos</span></div>${dayStrip()}<section class="guide-day"><div class="guide-intro"><div class="eyebrow">${dateLabel(d)} <span class="dot-separator">/</span> DIA ${selected+1}</div><h1>${d.city}<span class="heading-dot">.</span></h1><p class="day-tag">${d.title}</p><div class="route">${icon('pin')}${d.route}</div>${art(d.kind)}<div class="illustration-caption">${d.tag} <span>BE / NL</span></div></div><div class="guide-plan"><div class="section-heading"><h2>O plano de hoje</h2><span>${d.acts.length} paradas</span></div>${activities()}${stay()}${placeNote()}<div class="plan-footer"><span>Um plano, não uma corrida.</span>${dayControls()}</div></div></section><footer class="page-footer">Feito para ir junto.<span>Roteiro provisório · horários ilustrativos</span></footer></main>`;
}
function routeMap(d) {
 const nodes = [{x:130,y:156,label:'Bruges',i:3},{x:255,y:230,label:'Ghent',i:4},{x:408,y:163,label:'Antuérpia',i:7},{x:284,y:367,label:'Bruxelas',i:12},{x:540,y:386,label:'Liège',i:2},{x:627,y:290,label:'Maastricht',i:1},{x:580,y:104,label:'Eindhoven',i:8},{x:704,y:166,label:'Helmond',i:10},{x:733,y:234,label:'Asten',i:11},{x:721,y:354,label:'Valkenburg',i:9}];
 let nodeIndex = nodes.findIndex(n=>n.i===selected);
 if(nodeIndex<0) nodeIndex=selected===5||selected===6?4:3;
 return `<div class="route-map"><svg viewBox="0 0 850 520" role="img" aria-label="Mapa esquemático das cidades da viagem, sem escala"><defs><pattern id="dots" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#b1bca9"/></pattern></defs><rect width="850" height="520" fill="url(#dots)"/><path d="M0 0h242q-90 60-111 117T0 271" fill="#bdd7d5"/><path d="M0 406q160-103 312 18t342 0 196-43v139H0" fill="#d4ddc6"/><path d="M454 0q-36 98 18 144t77 109 158 27 143-29" fill="none" stroke="#abb7a0" stroke-width="2" stroke-dasharray="7 8"/><path d="M130 156 255 230 284 367 540 386 627 290 721 354 580 104 704 166 733 234" fill="none" stroke="#8e9d8b" stroke-width="3" stroke-dasharray="5 7"/><path d="m130 156 125 74 153-67 172-59" stroke="#42654e" stroke-width="4" fill="none"/><text x="100" y="425" class="map-country">BÉLGICA</text><text x="510" y="42" class="map-country">PAÍSES BAIXOS</text><g transform="translate(45 290) rotate(-18)"><path d="m0 0 15-48 15 48-15-10Z" fill="#456251"/><text x="11" y="-61" class="map-north">N</text></g>${nodes.map((n,j)=>`<g><circle cx="${n.x}" cy="${n.y}" r="${j===nodeIndex?16:8}" fill="${j===nodeIndex?'#bf583b':'#f8f5e9'}" stroke="${j===nodeIndex?'#bf583b':'#42654e'}" stroke-width="3"/>${j===nodeIndex?`<circle cx="${n.x}" cy="${n.y}" r="5" fill="#fff"/>`:''}<text x="${n.x}" y="${n.y+35}" text-anchor="middle" class="map-city">${n.label}</text></g>`).join('')}</svg>${nodes.map(n=>`<button class="map-hit" style="left:${n.x/8.5}%;top:${n.y/5.2}%" data-day="${n.i}" aria-label="Ver ${n.label}, ${days[n.i].date} de dezembro"></button>`).join('')}<span class="map-scale">Mapa afetivo, não está em escala.</span></div>`;
}
function atlas(d) {
 return `${header('por aí', 'Um inverno entre amigos')}<main class="atlas-shell"><div class="atlas-title"><div><span class="eyebrow">O CAMINHO TAMBÉM É A VIAGEM</span><h1>Onde a gente vai?</h1></div><span class="atlas-key"><i></i> Parada selecionada</span></div><div class="atlas-layout"><section class="atlas-detail"><div class="eyebrow">${dateLabel(d)}</div><h2>${d.city}</h2><p>${d.country}</p><div class="atlas-art">${art(d.kind)}</div><div class="route">${icon('car')}${d.route}</div><h3>Por aqui, hoje</h3>${activities()}${placeNote()}${dayControls()}</section><section class="map-panel" aria-label="Explorar a rota">${routeMap(d)}<div class="map-caption">Duas fronteiras.<br><em>Muitas histórias.</em></div><div class="map-legend">${icon('pin')} Toque em uma cidade para explorar o dia.</div></section></div>${dayStrip()}<footer class="page-footer">Escolha um dia ou uma parada no mapa.<span>Roteiro provisório · horários ilustrativos</span></footer></main>`;
}
function boarding(d) {
 return `${header('EN ROUTE', 'BE / NL · WINTER 2026')}<main class="boarding-shell"><div class="board-heading"><span class="eyebrow">PAINEL DA NOSSA VIAGEM</span><span class="board-status">${icon('people')} TODOS A BORDO</span></div><div class="departure-layout"><section class="departure-main"><div class="departure-meta"><span>${dateLabel(d)}</span><span>DESTINO ${String(selected+1).padStart(2,'0')}</span></div><h1 class="split-flap">${d.city}</h1><div class="departure-route">${icon('arrow')}${d.route}</div><div class="departure-table"><div class="table-head"><span>QUANDO</span><span>PRÓXIMA PARADA</span><span>DETALHES</span></div>${activities()}</div><div class="boarding-bottom">${stay()}${dayControls()}</div></section><aside class="boarding-pass"><div class="ticket-top"><span>TRAVEL TOGETHER</span>${icon('plane')}</div><span class="eyebrow">PASSE DO DIA</span><div class="ticket-number">${String(d.date).padStart(2,'0')}<small>DEZ<br>2026</small></div>${art(d.kind)}<div class="ticket-place">${d.city}<span>${d.country}</span></div><div class="ticket-tear"></div>${placeNote()}<div class="barcode" aria-hidden="true"></div><small class="ticket-foot">BOAS HISTÓRIAS NÃO CABEM NA MALA</small></aside></div>${dayStrip()}<footer class="page-footer">O próximo destino é melhor em boa companhia.<span>Horários ilustrativos · confirmar reservas</span></footer></main>`;
}
function postcards(d) {
 return `${header('a gente foi', 'Caderno de uma viagem')}<main class="postcards-shell"><div class="scrap-title"><div><span class="eyebrow">BÉLGICA + PAÍSES BAIXOS / DEZEMBRO 2026</span><h1>Vai render história.</h1></div><div class="round-stamp">14 DIAS<br><strong>BE + NL</strong><br>JUNTOS</div></div><div class="scrap-layout"><section class="postcard"><div class="tape"></div><div class="postcard-image"><span class="postcard-count">Nº ${String(selected+1).padStart(2,'0')}</span>${art(d.kind)}<span class="postmark">DEZ '26<br>COM AMIGOS</span></div><div class="postcard-caption"><div><h2>${d.city}</h2><p>${d.title}</p></div>${icon('sun')}</div></section><section class="scrap-plan"><div class="scrap-date">${dateLabel(d)}${dayControls()}</div><h2>O que vamos aprontar</h2>${activities('scrap-activities')}<div class="sticky-note"><span class="eyebrow">BILHETE PRO GRUPO</span>${placeNote()}<span class="handwritten">pra não esquecer!</span></div></section></div><div class="scrap-route">${icon('car')} ${d.route}<span>${icon('bed')} ${d.stay}</span></div>${dayStrip()}<footer class="page-footer">Leva um casaco. E espaço pras histórias.<span>Roteiro provisório · horários ilustrativos</span></footer></main>`;
}
function now(d) {
 return `${header('junto', 'Menos tela. Mais viagem.')}<main class="now-shell"><aside class="now-margin"><span class="eyebrow">UM DIA<br>DE CADA VEZ.</span><div class="margin-line"></div><span>02 a 15<br>dezembro<br>2026</span></aside><section class="now-card"><div class="now-date"><button data-step="-1" aria-label="Dia anterior" ${selected===0?'disabled':''}>${icon('left')}</button><button class="date-picker" data-calendar>${dateLabel(d)} ${icon('grid')}</button><button data-step="1" aria-label="Próximo dia" ${selected===13?'disabled':''}>${icon('arrow')}</button></div><span class="eyebrow now-country">${d.country}</span><h1>${d.city}</h1><p class="now-tag">${d.tag}</p><div class="now-illustration">${art(d.kind)}</div><div class="now-route">${icon('pin')} ${d.route}</div><div class="now-plan"><div class="section-heading"><h2>Só o plano de hoje.</h2><span>${d.acts.length} paradas</span></div>${activities()}${stay()}</div><button class="now-note" data-notes="place">${icon('note')}<span>O que precisamos saber<strong>Notas de ${d.city}</strong></span>${icon('arrow')}</button><div class="now-bottom"><button data-calendar>${icon('grid')} Todos os dias</button>${notesButton('Notas gerais')}</div></section><aside class="now-side"><div class="line-doodle">${icon('sun')}</div><p>A gente cuida<br>do plano.<br><em>Você aproveita.</em></p><small>Protótipo com<br>horários ilustrativos.</small></aside></main>`;
}
function week(d) {
 const weekStart = selected < 7 ? 0 : 7;
 return `${header('dias & lugares', 'Nossa viagem, de uma vez')}<main class="week-shell"><div class="week-heading"><div><span class="eyebrow">BÉLGICA & PAÍSES BAIXOS</span><h1>Dezembro<span>2026</span></h1></div><div class="week-controls"><button data-week="0" aria-pressed="${weekStart===0}">02 a 08 dez</button><button data-week="7" aria-pressed="${weekStart===7}">09 a 15 dez</button></div></div><div class="calendar-grid" aria-label="Visão de sete dias">${days.slice(weekStart,weekStart+7).map((day,index)=>{const i=index+weekStart;return `<button class="calendar-day ${selected===i?'selected':''}" data-day="${i}" aria-pressed="${selected===i}"><span class="calendar-weekday">${day.week}</span><strong class="calendar-number">${String(day.date).padStart(2,'0')}</strong><span class="calendar-art">${art(day.kind)}</span><strong class="calendar-city">${day.city}</strong><span class="calendar-activities">${day.acts.length} atividades ${icon('arrow')}</span><span class="calendar-stay">${icon('bed')}${day.stay}</span></button>`}).join('')}</div><section class="week-detail"><div class="week-day-summary"><span class="eyebrow">${dateLabel(d)}</span><h2>${d.city}</h2><p>${d.title}</p><div class="route">${icon('pin')}${d.route}</div>${dayControls()}</div><div class="week-activities"><h3>No roteiro</h3>${activities()}</div><aside class="week-notes"><span class="eyebrow">BLOCO DE NOTAS</span>${placeNote()}${notesButton('Ver notas da viagem')}</aside></section><footer class="page-footer">Planos claros. Espaço para mudar de ideia.<span>Roteiro provisório · horários ilustrativos</span></footer></main>`;
}
const dialog = document.getElementById('details');
function showDialog(title, content) {
 document.getElementById('dialog-content').innerHTML = `<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button data-close aria-label="Fechar">${icon('close')}</button></div>${content}`;
 dialog.showModal();
}
function syncURL() { const url = new URL(location.href); url.searchParams.set('variant',variant); url.searchParams.set('day',days[selected].date); history.replaceState(null,'',url); }
function changeDay(i) { selected = Math.max(0,Math.min(13,i)); syncURL(); render(); }
function changeVariant(v) { variant = v; syncURL(); render(); window.scrollTo(0,0); }
document.addEventListener('click', e => {
 const button = e.target.closest('button');
 if (!button) return;
 const data = button.dataset;
 if ('day' in data) { const insideDialog = dialog.contains(button); if (dialog.open) dialog.close(); changeDay(Number(data.day)); if(insideDialog) document.querySelector('[data-calendar]')?.focus(); else document.querySelector(`[data-day="${selected}"]`)?.focus({preventScroll:true}); }
 if ('step' in data) { changeDay(selected + Number(data.step)); document.querySelector(`[data-step="${data.step}"]:not(:disabled)`)?.focus({preventScroll:true}); }
 if ('variant' in data) { changeVariant(Number(data.variant)); document.querySelector(`#switcher [aria-current]`)?.focus({preventScroll:true}); }
 if ('week' in data) { changeDay(Number(data.week)); document.querySelector(`[data-week="${data.week}"]`)?.focus({preventScroll:true}); }
 if ('close' in data) dialog.close();
 if ('calendar' in data) showDialog('Escolha um dia', `<p class="dialog-subtitle">Dezembro de 2026 · roteiro provisório</p><div class="dialog-days">${days.map((d,i)=>`<button data-day="${i}" aria-pressed="${i===selected}"><strong>${d.date} <small>${d.week}</small></strong><span>${d.city}</span>${icon('arrow')}</button>`).join('')}</div>`);
 const d = days[selected];
 if ('activity' in data) { const a=d.acts[Number(data.activity)]; showDialog(a[1], `<div class="detail-illustration">${art(a[2])}</div><span class="eyebrow">${dateLabel(d)} · ${a[0]}</span><p class="detail-text">${a[3]}</p><div class="dialog-notice">${icon('note')}Horários ilustrativos. Confirme antes de sair.</div><a class="map-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(a[1]+' '+d.city.replace('?',''))}" target="_blank" rel="noopener noreferrer">Buscar no mapa ${icon('arrow')}</a>`); }
 if (data.notes==='place') showDialog(`Notas de ${d.city}`, `<span class="eyebrow">${dateLabel(d)}</span><p class="detail-text">${d.note}</p><div class="dialog-notice">${icon('bed')}${d.stay}</div><h3>Sobre os planos</h3><p>Este roteiro ainda está em aberto. Acordar horários e reservas com o grupo antes da viagem.</p>`);
 if (data.notes==='trip') showDialog('Notas da viagem', `<span class="eyebrow">BÉLGICA & PAÍSES BAIXOS · 02 A 15 DEZ 2026</span><div class="trip-notes"><section>${icon('bed')}<div><h3>Reservar hospedagem</h3><p>Hotel em Bruges e última noite em Bruxelas ainda precisam ser definidos.</p></div></section><section>${icon('star')}<div><h3>Natal, com confirmação</h3><p>Verificar calendário dos mercados e ingressos das cavernas de Valkenburg para 2026.</p></div></section><section>${icon('people')}<div><h3>Combinar com os amigos</h3><p>Confirmar encontros em Maastricht, Veldhoven, Helmond e Asten.</p></div></section><section>${icon('note')}<div><h3>Roteiro em aberto</h3><p>Ghent ou mais um dia em Bruges? As datas dos encontros seguem o quadro geral; o roteiro detalhado tem divergências.</p></div></section></div><div class="dialog-notice">Protótipo de leitura. Sem edição, reservas ou dados em tempo real.</div>`);
});
dialog.addEventListener('click',e=>{if(e.target===dialog) dialog.close();});
document.addEventListener('keydown', e => {
 if(dialog.open || e.altKey || e.ctrlKey || e.metaKey || e.target.closest('input,textarea,select,[contenteditable="true"]')) return;
 if(e.key==='ArrowLeft' || e.key==='ArrowRight') {e.preventDefault();changeVariant((variant-1+(e.key==='ArrowRight'?1:5))%6+1);document.querySelector('#switcher [aria-current]')?.focus({preventScroll:true});}
});
render();
